import numpy as np

def softmax(x):
    e_x = np.exp(x - np.max(x, axis=-1, keepdims=True))
    return e_x / np.sum(e_x, axis=-1, keepdims=True)

def masked_lm_forward(token_ids, mask_token_id, vocab_size,
                       model_forward, mask_prob=0.15):
    masked_ids = token_ids.copy()
    mask_positions = np.where(np.random.random(len(token_ids)) < mask_prob)[0]
    for pos in mask_positions:
        r = np.random.random()
        if r < 0.8:
            masked_ids[pos] = mask_token_id
        elif r < 0.9:
            masked_ids[pos] = np.random.randint(0, vocab_size)
    logits = model_forward(masked_ids)
    probs = softmax(logits[mask_positions])
    original = token_ids[mask_positions]
    loss = -np.mean(np.log(probs[np.arange(len(original)), original] + 1e-9))
    predictions = np.argmax(logits[mask_positions], axis=-1)
    return {"loss": loss, "predictions": predictions, "masked_positions": mask_positions}
